import{_ as r,c as o,o as n,a0 as l}from"./chunks/framework._Jgw3yL-.js";const f=JSON.parse('{"title":"定位板-建議選擇預設的PC材質","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/基础定制/定位板选择.md","filePath":"zh-HK/基础定制/定位板选择.md"}'),s={name:"zh-HK/基础定制/定位板选择.md"};function e(g,t,a,i,d,u){return n(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="定位板-建議選擇預設的pc材質" tabindex="-1">定位板-建議選擇預設的PC材質 <a class="header-anchor" href="#定位板-建議選擇預設的pc材質" aria-label="Permalink to &quot;定位板-建議選擇預設的PC材質&quot;">​</a></h1><p><strong>重要提示</strong>：定位板只是影響鍵盤聲音和手感的因素之一。<strong>軸體、鍵帽、PCB板、聲音包、鍵盤結構</strong> 等同樣至關重要。一個PC定位板搭配線性靜音軸和填充包，可以做到幾乎無聲；而同樣的PC板搭配清脆的段落軸，聲音也會變得響亮。因此，需要將定位板視為整個鍵盤系統的一部分來考量。</p><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h2><h3 id="核心對比總覽表" tabindex="-1">核心對比總覽表 <a class="header-anchor" href="#核心對比總覽表" aria-label="Permalink to &quot;核心對比總覽表&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">材質</th><th style="text-align:left;">聲音大小/風格</th><th style="text-align:left;">材質軟硬</th><th style="text-align:left;">材質顏色/外觀</th><th style="text-align:left;">透光性</th><th style="text-align:left;">主要優缺點</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>鋼</strong></td><td style="text-align:left;"><strong>最大、最響</strong><br>聲音清脆、高頻、有金屬迴響（&quot;鋼印&quot;聲）</td><td style="text-align:left;"><strong>最硬</strong><br>形變幾乎為零，手感一致性極高</td><td style="text-align:left;">銀色、黑色（電泳）為主，可電鍍其他顏色</td><td style="text-align:left;"><strong>不透光</strong><br>完全阻擋光線</td><td style="text-align:left;"><strong>優</strong>：手感反饋最直接，壽命極長，支撐性強<br><strong>缺</strong>：聲音刺耳，沉重，可能引起空腔音</td></tr><tr><td style="text-align:left;"><strong>黃銅</strong></td><td style="text-align:left;"><strong>中等偏小、低沉</strong><br>聲音沉悶、厚重、有&quot;石子&quot;音或&quot;麻將&quot;音</td><td style="text-align:left;"><strong>非常硬</strong><br>比鋼稍軟一丁點，但手感上幾乎無差別</td><td style="text-align:left;"><strong>金色/古銅色</strong><br>易氧化變暗，有獨特質感</td><td style="text-align:left;"><strong>不透光</strong><br>完全阻擋光線</td><td style="text-align:left;"><strong>優</strong>：聲音好聽（主觀），手感扎實穩重，高端感<br><strong>缺</strong>：非常重，價格昂貴，易氧化變色</td></tr><tr><td style="text-align:left;"><strong>鋁</strong></td><td style="text-align:left;"><strong>中等、清亮</strong><br>聲音介於鋼和PC之間，比鋼柔和，比PC脆</td><td style="text-align:left;"><strong>硬</strong><br>比鋼和銅軟，但仍有很好的支撐性</td><td style="text-align:left;"><strong>銀色、黑色、多彩陽極氧化色</strong><br>顏色選擇最豐富</td><td style="text-align:left;"><strong>不透光</strong><br>完全阻擋光線</td><td style="text-align:left;"><strong>優</strong>：重量輕，顏色多，手感和聲音的&quot;萬金油&quot;<br><strong>缺</strong>：可能在某些大力敲擊下有輕微形變</td></tr><tr><td style="text-align:left;"><strong>PC</strong></td><td style="text-align:left;"><strong>最小、最悶</strong><br>聲音沉悶、柔和、有&quot;雨滴&quot;或&quot;鼓&quot;聲，能消除雜音</td><td style="text-align:left;"><strong>最軟</strong><br>有明顯的形變，提供&quot;軟彈&quot;手感</td><td style="text-align:left;"><strong>半透明/乳白色</strong><br>非常適合搭配RGB燈光</td><td style="text-align:left;"><strong>高透光</strong><br>光線透過率高，柔光效果好</td><td style="text-align:left;"><strong>優</strong>：聲音最安靜、最柔和，提供獨特的軟彈手感<br><strong>缺</strong>：支撐性差，手感一致性相對較低，可能太&quot;肉&quot;</td></tr><tr><td style="text-align:left;"><strong>FR4</strong></td><td style="text-align:left;"><strong>中等偏悶、均衡</strong><br>聲音清脆中帶點悶，介於PC和鋁之間，常被描述為&quot;均衡&quot;</td><td style="text-align:left;"><strong>中等偏軟</strong><br>比PC硬，比鋁軟，有一定韌性</td><td style="text-align:left;"><strong>通常為綠色/黑色</strong>，可定制圖案<br>外觀一般，功能性為主</td><td style="text-align:left;"><strong>半透光</strong><br>僅輕微光線可通過，效果一般</td><td style="text-align:left;"><strong>優</strong>：兼具一定的軟彈和清晰的反饋，聲音表現均衡<br><strong>缺</strong>：外觀普通，高端感不足</td></tr></tbody></table><h2 id="詳細分析與解讀" tabindex="-1">詳細分析與解讀 <a class="header-anchor" href="#詳細分析與解讀" aria-label="Permalink to &quot;詳細分析與解讀&quot;">​</a></h2><h3 id="_1-聲音大小與風格" tabindex="-1">1. 聲音大小與風格 <a class="header-anchor" href="#_1-聲音大小與風格" aria-label="Permalink to &quot;1. 聲音大小與風格&quot;">​</a></h3><ul><li><strong>追求極致安靜/悶響音</strong>：<strong>PC &gt; FR4 &gt; 銅 &gt; 鋁 &gt; 鋼</strong></li><li>PC材質能最大程度地吸收震動和高頻噪音，產生一種低沉、圓潤的&quot;噗噗&quot;聲，是打造&quot;Hifi&quot;打字音的常見選擇。</li><li><strong>追求清脆響亮</strong>：<strong>鋼 &gt; 鋁 &gt; FR4 &gt; 銅 &gt; PC</strong></li><li>鋼定位板與軸體撞擊會產生非常明亮、清脆的聲音，伴隨長久的迴響，有些人覺得這很&quot;工業感&quot;，有些人則覺得刺耳。</li><li><strong>追求均衡或特定音色</strong>：</li><li><strong>PC</strong>：提供獨特的低沉、厚重的&quot;石子音&quot;，非常有質感，容易出石子音和麻將音。</li><li><strong>FR4</strong>：被許多人認為是聲音的&quot;平衡點&quot;，既有一定的脆度，又不失柔和。</li><li><strong>鋁</strong>：是最常見的選擇，聲音清亮但不聒噪，適合大多數人。</li></ul><h3 id="_2-材質軟硬與手感" tabindex="-1">2. 材質軟硬與手感 <a class="header-anchor" href="#_2-材質軟硬與手感" aria-label="Permalink to &quot;2. 材質軟硬與手感&quot;">​</a></h3><ul><li><strong>追求一致、直接、快速回饋</strong>：<strong>鋼 ≈ 銅 &gt; 鋁 &gt; FR4 &gt; PC</strong></li><li>鋼和銅幾乎不會發生形變，你按下去的力會立刻、完全地傳遞給軸體和PCB板，手感乾淨俐落，非常適合遊戲玩家。</li><li><strong>追求&quot;軟彈&quot;手感（Gasket結構精髓）</strong>：<strong>PC &gt; FR4 &gt; 鋁 &gt; 銅 ≈ 鋼</strong></li><li>PC板在打字時會產生肉眼可見的形變，這種&quot;下沉感&quot;可以緩衝手指的衝擊，提供非常柔和、Q彈的打字體驗，長時間碼字更舒適。這是目前客製化鍵盤的主流趨勢。</li></ul><h3 id="_3-材質顏色與外觀" tabindex="-1">3. 材質顏色與外觀 <a class="header-anchor" href="#_3-材質顏色與外觀" aria-label="Permalink to &quot;3. 材質顏色與外觀&quot;">​</a></h3><ul><li><strong>顏色多樣性</strong>：<strong>鋁 &gt; 鋼 &gt; PC &gt; 銅 &gt; FR4</strong></li><li><strong>鋁</strong>：透過陽極氧化幾乎可以製成任何顏色，是外觀客製化的最佳選擇。</li><li><strong>鋼</strong>：主要以電泳上色，常見為黑白，也可做其他顏色但選擇較少。</li><li><strong>PC</strong>：通常是半透明或乳白色，主要為了透光。</li><li><strong>銅</strong>：只有固有的金色，且會隨時間氧化成更深沉的古銅色，這是一種獨特的&quot;養牛&quot;樂趣。</li><li><strong>FR4</strong>：外觀是其短板，通常是電路板一樣的綠色或黑色，雖可定製圖案但質感一般。</li></ul><h2 id="總結與選購建議" tabindex="-1">總結與選購建議 <a class="header-anchor" href="#總結與選購建議" aria-label="Permalink to &quot;總結與選購建議&quot;">​</a></h2><ul><li><strong>遊戲玩家/喜歡清脆手感</strong>：首選 <strong>鋼</strong> 或 <strong>鋁</strong>。鋼回饋最直接，鋁則是更輕、更均衡的選擇。</li><li><strong>碼字工作者/追求Hifi打字音</strong>：首選 <strong>PC</strong>。它們能提供柔和安靜的聲音和舒適的軟彈手感。</li><li><strong>客製化發燒友/追求高端質感</strong>：可以考慮 <strong>銅</strong>。它重量大、聲音獨特，有很強的&quot;溢價感&quot;和把玩價值。</li><li><strong>新手入門/不知道選什麼</strong>：選擇 <strong>PC</strong> 定位板。它是行業標準，在手感、聲音、重量和價格上取得了最佳平衡，是最不會出錯的選擇。</li></ul>',14)])])}const q=r(s,[["render",e]]);export{f as __pageData,q as default};
